#include <iostream>
#include <type_traits>
using namespace std;

struct NoNoexcept {
    int v;
    explicit NoNoexcept(int x) : v(x) {}
    NoNoexcept(const NoNoexcept& o) : v(o.v) {}
    NoNoexcept(NoNoexcept&& o) : v(o.v) {}          // 未标 noexcept
};

struct WithNoexcept {
    int v;
    explicit WithNoexcept(int x) : v(x) {}
    WithNoexcept(const WithNoexcept& o) : v(o.v) {}
    WithNoexcept(WithNoexcept&& o) noexcept : v(o.v) {}
};

int main() {
    cout << boolalpha;
    cout << "is_nothrow_move_constructible<NoNoexcept>   = "
         << is_nothrow_move_constructible_v<NoNoexcept> << "\n";
    cout << "is_nothrow_move_constructible<WithNoexcept> = "
         << is_nothrow_move_constructible_v<WithNoexcept> << "\n";
    cout << "\nvector 扩容要保证强异常安全，内部用 move_if_noexcept 判定：\n";
    cout << "  NoNoexcept   的移动可能抛异常 -> 退化为拷贝构造（慢但安全）\n";
    cout << "  WithNoexcept 的移动保证不抛   -> 真正使用移动构造（快）\n";
    cout << "所以：自定义移动构造请一律标 noexcept，否则性能白给\n";
}
